from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, computed_field
from typing import Optional

router = APIRouter(prefix="/hr/employees")

class EmployeePublicProfile(BaseModel):
    id: str
    full_name: str
    department: str
    job_title: str
    _internal_salary_cents: int = 0
    _ssn_last4: str = ""

    @computed_field
    @property
    def estimated_annual_salary(self) -> float:
        # Computed field serialized into JSON response
        return round(self._internal_salary_cents / 100.0, 2)

    @computed_field
    @property
    def tax_identifier_suffix(self) -> str:
        return f"XXX-XX-{self._ssn_last4}"

@router.get("/{employee_id}/public-profile", response_model=EmployeePublicProfile)
async def get_employee_public_profile(
    employee_id: str,
    hr_service: HRDirectoryService = Depends(get_hr_service),
    colleague: EmployeeUser = Depends(get_current_employee)
):
    emp = await hr_service.find_employee(employee_id)
    if not emp:
        raise HTTPException(status_code=404, detail="Employee not found")

    profile = EmployeePublicProfile(
        id=emp.id,
        full_name=emp.full_name,
        department=emp.department,
        job_title=emp.job_title
    )
    profile._internal_salary_cents = emp.salary_cents
    profile._ssn_last4 = emp.ssn[-4:]
    return profile
